// Input: items[0].json['Appointment time'] (ISO string with timezone offset)
// Output: { isBusinessHour, reason, window, timezone }

const TZ = 'America/Chicago';
const windowLabel = 'Mon–Fri 07:00–17:00';

const reqIso = $('Webhook2').first().json.body.message.toolCalls[0].function.arguments.preferredCallbackTime;
if (!reqIso || typeof reqIso !== 'string') {
  return [{ json: { isBusinessHour: false, reason: 'missing_preferredCallbackTime', window: windowLabel, timezone: TZ } }];
}

// If no timezone offset is present, assume Chicago time
const reqIsoWithTz = reqIso.includes('Z') || reqIso.includes('+') || /\-\d{2}:\d{2}$/.test(reqIso) 
  ? reqIso 
  : reqIso + '-06:00';

const req = new Date(reqIsoWithTz);
if (isNaN(req.getTime())) {
  return [{ json: { isBusinessHour: false, reason: 'invalid_datetime_format', window: windowLabel, timezone: TZ } }];
}

function zonedParts(date, timeZone) {
  const fmt = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric', month: 'numeric', day: 'numeric',
    hour: 'numeric', minute: 'numeric',
    weekday: 'short', hour12: false
  });
  const parts = fmt.formatToParts(date).reduce((acc, p) => (acc[p.type] = p.value, acc), {});
  return {
    year: Number(parts.year),
    month: Number(parts.month),
    day: Number(parts.day),
    hour: Number(parts.hour),
    minute: Number(parts.minute),
    weekday: parts.weekday
  };
}

function usFederalHolidaysForYear(year, timeZone) {
  const DOW = { Sun:0, Mon:1, Tue:2, Wed:3, Thu:4, Fri:5, Sat:6 };
  const dayMs = 24*3600*1000;

  const makeDate = (y, m, d) =>
    new Date(Date.UTC(y, m-1, d, 12, 0, 0));

  const weekdayOf = (date, tz) =>
    new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'short' }).format(date);

  const nthDowOfMonth = (y, m, dow, n) => {
    let d = makeDate(y, m, 1);
    while (['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(weekdayOf(d, timeZone)) !== dow)
      d = new Date(d.getTime() + dayMs);
    d = new Date(d.getTime() + (n-1)*7*dayMs);
    return d;
  };

  const lastDowOfMonth = (y, m, dow) => {
    let d = makeDate(y, m+1, 1);
    d = new Date(d.getTime() - dayMs);
    while (['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(weekdayOf(d, timeZone)) !== dow)
      d = new Date(d.getTime() - dayMs);
    return d;
  };

  const DOW_IDX = { Sun:0, Mon:1, Tue:2, Wed:3, Thu:4, Fri:5, Sat:6 };
  const observed = (d) => {
    const wd = DOW_IDX[weekdayOf(d, timeZone)];
    if (wd === DOW.Sat) return new Date(d.getTime() - dayMs);
    if (wd === DOW.Sun) return new Date(d.getTime() + dayMs);
    return d;
  };

  const newYearsDay      = observed(makeDate(year, 1, 1));
  const mlkDay           = nthDowOfMonth(year, 1,  1, 3);
  const presidentsDay    = nthDowOfMonth(year, 2,  1, 3);
  const memorialDay      = lastDowOfMonth(year, 5, 1);
  const juneteenth       = observed(makeDate(year, 6, 19));
  const independenceDay  = observed(makeDate(year, 7, 4));
  const laborDay         = nthDowOfMonth(year, 9,  1, 1);
  const columbusDay      = nthDowOfMonth(year, 10, 1, 2);
  const veteransDay      = observed(makeDate(year, 11, 11));
  const thanksgiving     = nthDowOfMonth(year, 11, 4, 4);
  const christmasDay     = observed(makeDate(year, 12, 25));

  return [
    newYearsDay, mlkDay, presidentsDay, memorialDay, juneteenth,
    independenceDay, laborDay, columbusDay, veteransDay, thanksgiving, christmasDay
  ];
}

function sameYMD(a, b, tz) {
  const pa = zonedParts(a, tz);
  const pb = zonedParts(b, tz);
  return pa.year===pb.year && pa.month===pb.month && pa.day===pb.day;
}

// Check business hours
const p = zonedParts(req, TZ);
const isWeekday = ['Mon','Tue','Wed','Thu','Fri'].includes(p.weekday);

// Check time: Monday-Friday 7 AM - 5 PM (07:00 - 17:00)
let withinTime = false;
let timeReason = 'within_hours';

if (isWeekday) {
  withinTime = (p.hour >= 7 && p.hour < 17);
  if (p.hour < 7) timeReason = 'before_open';
  if (p.hour >= 17) timeReason = 'after_close';
}

const holidays = usFederalHolidaysForYear(p.year, TZ);
const isHoliday = holidays.some(h => sameYMD(h, req, TZ));

let isBusinessHour = isWeekday && withinTime && !isHoliday;
let reason = 'within_hours';
if (!isWeekday) reason = 'weekend';
else if (!withinTime) reason = timeReason;
else if (isHoliday) reason = 'holiday';

return [{
  json: {
    isBusinessHour,
    reason,
    window: windowLabel,
    timezone: TZ
  }
}];

